using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Configuration;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

// Configuration
var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

// Register services
var services = new ServiceCollection();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

services.AddSingleton<ResearchTools>();

var serviceProvider = services.BuildServiceProvider();

// Set up the agent with tools
var chatClient = serviceProvider.GetRequiredService<IChatClient>();
var researchTools = serviceProvider.GetRequiredService<ResearchTools>();

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ],
};

// Create the agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic using the available tools.

        Workflow:
        1. Use SearchWeb to find information about the topic (make multiple searches with different queries)
        2. Use TakeNote to save important findings as you go
        3. Use GetNotes to review all your notes
        4. Provide a comprehensive summary of your research findings

        Be thorough — search from multiple angles to build a complete picture.
        """,
};

// Run the agent
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = chatOptions,
};

await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");
Console.WriteLine($"Notes collected: {researchTools.NoteCount}");

// --- Tool definitions ---

public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public string SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search results — replace with a real search API (e.g., Bing Search)
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");

        return $$"""
            Search results for "{{query}}":

            1. {{query}} - Wikipedia Overview
               Comprehensive encyclopedia article covering the main aspects, history, and significance of {{query}}.

            2. Recent Developments in {{query}} - TechNews
               Latest advancements and breakthroughs related to {{query}} from the past year, including industry adoption and research progress.

            3. {{query}} Explained: A Beginner's Guide - Educational Resource
               An accessible introduction covering fundamental concepts, common applications, and key terminology.

            4. Expert Analysis: The Future of {{query}} - Research Journal
               Peer-reviewed analysis of current trends, challenges, and projected developments over the next decade.
            """;
    }

    [Description("Save a note about a research finding. Use this to record important information.")]
    public string TakeNote(
        [Description("The content of the note to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

