+    ChatOptions = chatOptions,
+};
+
+await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
+{
+    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
+    {
+        Console.Write(message.Text);
+    }
+}
+
+Console.WriteLine("\n\n=== Research Complete ===");
+Console.WriteLine($"Notes collected: {researchTools.NoteCount}");
+
+// --- Tool definitions ---
+
+public sealed class ResearchTools
+{
+    private readonly List<string> _notes = [];
+
+    public int NoteCount => _notes.Count;
+
+    [Description("Search the web for information on a query. Returns search result snippets.")]
+    public string SearchWeb(
+        [Description("The search query to look up")] string query)
+    {
+        // Simulated web search results — replace with a real search API (e.g., Bing Search)
+        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");
+
+        return $$"""
+            Search results for "{{query}}":
+            
+            1. {{query}} - Wikipedia Overview
+               Comprehensive encyclopedia article covering the main aspects, history, and significance of {{query}}.
+            
+            2. Recent Developments in {{query}} - TechNews
+               Latest advancements and breakthroughs related to {{query}} from the past year, including industry adoption and research progress.
+            
+            3. {{query}} Explained: A Beginner's Guide - Educational Resource
+               An accessible introduction covering fundamental concepts, common applications, and key terminology.
+            
+            4. Expert Analysis: The Future of {{query}} - Research Journal
+               Peer-reviewed analysis of current trends, challenges, and projected developments over the next decade.
+            """;
+    }
+
+    [Description("Save a note about a research finding. Use this to record important information.")]
+    public string TakeNote(
+        [Description("The content of the note to save")] string note)
+    {
+        _notes.Add(note);
+        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
+        return $"Note saved successfully. You now have {_notes.Count} note(s).";
+    }
+
+    [Description("Retrieve all saved research notes.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
+        return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
+    }
+}

